SELECT 'A01_entorno_servidor' AS chequeo, VERSION() AS version_mysql, @@version_comment AS distribucion, DATABASE() AS base_actual, @@session.time_zone AS tz_sesion, @@global.time_zone AS tz_global, @@system_time_zone AS tz_sistema, NOW() AS ahora_sesion, UTC_TIMESTAMP() AS ahora_utc, @@session.transaction_read_only AS sesion_solo_lectura, @@session.transaction_isolation AS aislamiento, @@sql_mode AS sql_mode, @@lower_case_table_names AS lower_case_table_names, @@event_scheduler AS event_scheduler, @@innodb_strict_mode AS innodb_strict_mode;

SELECT 'A02_privilegios_usuario_conectado' AS chequeo, 'GLOBAL' AS ambito, privilege_type, is_grantable FROM information_schema.user_privileges WHERE grantee = CONCAT('''', SUBSTRING_INDEX(CURRENT_USER(), '@', 1), '''@''', SUBSTRING_INDEX(CURRENT_USER(), '@', -1), '''') UNION ALL SELECT 'A02_privilegios_usuario_conectado', CONCAT('BASE ', table_schema), privilege_type, is_grantable FROM information_schema.schema_privileges WHERE table_schema = DATABASE() AND grantee = CONCAT('''', SUBSTRING_INDEX(CURRENT_USER(), '@', 1), '''@''', SUBSTRING_INDEX(CURRENT_USER(), '@', -1), '''') ORDER BY ambito, privilege_type;

SELECT 'A04_resumen_privilegios_usuario_conectado' AS chequeo, COUNT(*) AS privilegios_globales, SUM(privilege_type IN ('SUPER', 'SYSTEM_USER', 'CREATE USER', 'GRANT OPTION', 'SHUTDOWN', 'FILE')) AS privilegios_administrativos, SUM(privilege_type IN ('DROP', 'ALTER', 'CREATE')) AS privilegios_ddl_globales, MAX(is_grantable) AS puede_otorgar FROM information_schema.user_privileges WHERE grantee = CONCAT('''', SUBSTRING_INDEX(CURRENT_USER(), '@', 1), '''@''', SUBSTRING_INDEX(CURRENT_USER(), '@', -1), '''');

SELECT 'A03_charset_base' AS chequeo, schema_name, default_character_set_name, default_collation_name FROM information_schema.schemata WHERE schema_name = DATABASE();

SELECT 'B01_inventario_tablas' AS chequeo, table_name, table_type, engine, table_rows AS filas_aprox, table_collation, create_time, update_time FROM information_schema.tables WHERE table_schema = DATABASE() ORDER BY table_name;

SELECT 'B02_tablas_marketplace_esperadas' AS chequeo, e.t AS tabla_esperada, IF(t.table_name IS NULL, 'FALTA', 'OK') AS estado, t.engine, t.table_collation, t.create_time FROM (SELECT 'districts' AS t UNION ALL SELECT 'marketplace_cities' UNION ALL SELECT 'organizations' UNION ALL SELECT 'organization_roles' UNION ALL SELECT 'permissions' UNION ALL SELECT 'organization_role_permissions' UNION ALL SELECT 'organization_members' UNION ALL SELECT 'establishment_statuses' UNION ALL SELECT 'establishments' UNION ALL SELECT 'establishment_status_history' UNION ALL SELECT 'space_types' UNION ALL SELECT 'spaces' UNION ALL SELECT 'features' UNION ALL SELECT 'space_features' UNION ALL SELECT 'space_block_types' UNION ALL SELECT 'space_blocks' UNION ALL SELECT 'services' UNION ALL SELECT 'service_providers' UNION ALL SELECT 'establishment_services' UNION ALL SELECT 'booking_request_statuses' UNION ALL SELECT 'booking_requests' UNION ALL SELECT 'booking_request_status_history' UNION ALL SELECT 'quote_statuses' UNION ALL SELECT 'quote_concepts' UNION ALL SELECT 'quotes' UNION ALL SELECT 'quote_items' UNION ALL SELECT 'quote_status_history' UNION ALL SELECT 'reservation_statuses' UNION ALL SELECT 'reservations' UNION ALL SELECT 'reservation_status_history' UNION ALL SELECT 'reservation_services' UNION ALL SELECT 'reservation_agreements' UNION ALL SELECT 'agreement_acceptances' UNION ALL SELECT 'space_occupancy_slots' UNION ALL SELECT 'card_brands' UNION ALL SELECT 'payment_statuses' UNION ALL SELECT 'refund_statuses' UNION ALL SELECT 'payments' UNION ALL SELECT 'refunds' UNION ALL SELECT 'concert_reservations' UNION ALL SELECT 'currencies' UNION ALL SELECT 'payment_methods' UNION ALL SELECT 'establishment_slot_modes' UNION ALL SELECT 'users' UNION ALL SELECT 'roles' UNION ALL SELECT 'user_roles' UNION ALL SELECT 'provinces' UNION ALL SELECT 'cities' UNION ALL SELECT 'venues' UNION ALL SELECT 'concerts') AS e LEFT JOIN information_schema.tables t ON t.table_schema = DATABASE() AND t.table_name = e.t ORDER BY estado, e.t;

SELECT 'B03_tablas_no_marketplace_reconstruidas_durante_la_migracion' AS chequeo, t.table_name, t.create_time FROM information_schema.tables t WHERE t.table_schema = DATABASE() AND t.create_time >= (SELECT MIN(x.create_time) FROM information_schema.tables x WHERE x.table_schema = DATABASE() AND x.table_name IN ('districts', 'marketplace_cities', 'organizations')) AND t.table_name NOT IN ('districts', 'marketplace_cities', 'organizations', 'organization_roles', 'permissions', 'organization_role_permissions', 'organization_members', 'establishment_statuses', 'establishments', 'establishment_status_history', 'space_types', 'spaces', 'features', 'space_features', 'space_block_types', 'space_blocks', 'services', 'service_providers', 'establishment_services', 'booking_request_statuses', 'booking_requests', 'booking_request_status_history', 'quote_statuses', 'quote_concepts', 'quotes', 'quote_items', 'quote_status_history', 'reservation_statuses', 'reservations', 'reservation_status_history', 'reservation_services', 'reservation_agreements', 'agreement_acceptances', 'space_occupancy_slots', 'card_brands', 'payment_statuses', 'refund_statuses', 'payments', 'refunds', 'concert_reservations', 'currencies', 'payment_methods', 'establishment_slot_modes') ORDER BY t.table_name;

SELECT 'C01_columnas_marketplace_y_base' AS chequeo, table_name, ordinal_position AS pos, column_name, column_type, is_nullable, column_default, extra, generation_expression FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name IN ('districts', 'marketplace_cities', 'organizations', 'organization_members', 'establishments', 'establishment_status_history', 'spaces', 'space_blocks', 'establishment_services', 'booking_requests', 'quotes', 'quote_items', 'reservation_statuses', 'reservations', 'reservation_services', 'payments', 'refunds', 'concert_reservations', 'space_occupancy_slots', 'currencies', 'payment_methods', 'establishment_slot_modes', 'provinces', 'cities', 'venues') ORDER BY table_name, ordinal_position;

SELECT 'C02_columnas_esperadas_estado_final' AS chequeo, e.t AS tabla, e.c AS columna, e.n AS nullable_esperado, c.is_nullable AS nullable_real, c.column_type, CASE WHEN c.column_name IS NULL THEN 'FALTA' WHEN c.is_nullable <> e.n THEN 'NULABILIDAD_DISTINTA' ELSE 'OK' END AS estado FROM (SELECT 'cities' AS t, 'district_id' AS c, 'YES' AS n UNION ALL SELECT 'establishments', 'organization_id', 'YES' UNION ALL SELECT 'establishments', 'venue_id', 'NO' UNION ALL SELECT 'establishments', 'city_id', 'NO' UNION ALL SELECT 'establishments', 'status_id', 'NO' UNION ALL SELECT 'spaces', 'is_whole_venue', 'NO' UNION ALL SELECT 'spaces', 'whole_venue_key', 'YES' UNION ALL SELECT 'space_blocks', 'establishment_id', 'NO' UNION ALL SELECT 'booking_requests', 'establishment_id', 'NO' UNION ALL SELECT 'quotes', 'space_id', 'NO' UNION ALL SELECT 'quotes', 'establishment_id', 'NO' UNION ALL SELECT 'quotes', 'currency_code', 'NO' UNION ALL SELECT 'quote_items', 'establishment_id', 'NO' UNION ALL SELECT 'reservation_statuses', 'is_hold', 'NO' UNION ALL SELECT 'reservation_statuses', 'blocks_space', 'NO' UNION ALL SELECT 'reservations', 'establishment_id', 'NO' UNION ALL SELECT 'reservations', 'venue_id', 'NO' UNION ALL SELECT 'reservations', 'currency_code', 'NO' UNION ALL SELECT 'reservations', 'status_is_hold', 'NO' UNION ALL SELECT 'reservations', 'status_blocks_space', 'NO' UNION ALL SELECT 'reservations', 'hold_expires_at', 'YES' UNION ALL SELECT 'reservation_services', 'establishment_id', 'NO' UNION ALL SELECT 'payments', 'currency_code', 'NO' UNION ALL SELECT 'payments', 'payment_method_id', 'NO' UNION ALL SELECT 'payments', 'method_requires_card', 'NO' UNION ALL SELECT 'refunds', 'currency_code', 'NO' UNION ALL SELECT 'concert_reservations', 'venue_id', 'NO' UNION ALL SELECT 'space_occupancy_slots', 'establishment_id', 'NO' UNION ALL SELECT 'space_occupancy_slots', 'is_whole_venue', 'NO' UNION ALL SELECT 'space_occupancy_slots', 'block_id', 'YES' UNION ALL SELECT 'space_occupancy_slots', 'reservation_id', 'YES' UNION ALL SELECT 'space_occupancy_slots', 'reservation_blocks_space', 'YES' UNION ALL SELECT 'establishment_slot_modes', 'establishment_id', 'NO' UNION ALL SELECT 'establishment_slot_modes', 'slot_start', 'NO' UNION ALL SELECT 'establishment_slot_modes', 'is_whole_venue', 'NO' UNION ALL SELECT 'payment_methods', 'requires_card', 'NO' UNION ALL SELECT 'currencies', 'code', 'NO') AS e LEFT JOIN information_schema.columns c ON c.table_schema = DATABASE() AND c.table_name = e.t AND c.column_name = e.c ORDER BY estado, e.t, e.c;

SELECT 'C03_columnas_que_deben_haberse_eliminado' AS chequeo, COUNT(*) AS presentes, GROUP_CONCAT(CONCAT(table_name, '.', column_name) ORDER BY column_name) AS columnas FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'establishments' AND column_name IN ('name', 'address');

SELECT 'C04_default_reservations_created_at' AS chequeo, column_name, column_type, column_default, extra FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'reservations' AND column_name IN ('created_at', 'updated_at', 'hold_expires_at') ORDER BY column_name;

SELECT 'D01_indices_marketplace' AS chequeo, table_name, index_name, MIN(non_unique) AS non_unique, GROUP_CONCAT(column_name ORDER BY seq_in_index) AS columnas, MAX(index_type) AS tipo FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name IN ('districts', 'marketplace_cities', 'organizations', 'organization_members', 'establishments', 'establishment_status_history', 'spaces', 'space_blocks', 'establishment_services', 'booking_requests', 'quotes', 'quote_items', 'reservation_statuses', 'reservations', 'reservation_services', 'payments', 'refunds', 'concert_reservations', 'space_occupancy_slots', 'currencies', 'payment_methods', 'establishment_slot_modes', 'cities', 'venues', 'concerts') GROUP BY table_name, index_name ORDER BY table_name, index_name;

SELECT 'D02_indices_esperados_por_la_migracion' AS chequeo, e.t AS tabla, e.i AS indice, e.d AS esperado, c.s AS real_, CASE WHEN c.s IS NULL THEN 'FALTA' WHEN c.s <> e.d THEN 'DISTINTO' ELSE 'OK' END AS estado FROM (SELECT 'venues' AS t, 'uq_venues_id_city' AS i, 'U:id,city_id' AS d UNION ALL SELECT 'concerts', 'uq_concerts_id_venue', 'U:id,venue_id' UNION ALL SELECT 'establishments', 'uq_establishments_id_venue', 'U:id,venue_id' UNION ALL SELECT 'establishments', 'uq_establishments_venue', 'U:venue_id' UNION ALL SELECT 'establishments', 'idx_establishments_city', 'N:city_id' UNION ALL SELECT 'establishments', 'idx_establishments_venue_city', 'N:venue_id,city_id' UNION ALL SELECT 'spaces', 'uq_spaces_establishment_whole_venue', 'U:establishment_id,whole_venue_key' UNION ALL SELECT 'spaces', 'uq_spaces_id_establishment', 'U:id,establishment_id' UNION ALL SELECT 'spaces', 'uq_spaces_id_establishment_whole', 'U:id,establishment_id,is_whole_venue' UNION ALL SELECT 'space_blocks', 'uq_space_blocks_id_space_establishment', 'U:id,space_id,establishment_id' UNION ALL SELECT 'space_blocks', 'idx_space_blocks_space_establishment', 'N:space_id,establishment_id' UNION ALL SELECT 'establishment_services', 'uq_establishment_services_id_establishment', 'U:id,establishment_id' UNION ALL SELECT 'booking_requests', 'uq_booking_requests_id_space_establishment', 'U:id,space_id,establishment_id' UNION ALL SELECT 'booking_requests', 'idx_booking_requests_space_establishment', 'N:space_id,establishment_id' UNION ALL SELECT 'quotes', 'uq_quotes_id_establishment', 'U:id,establishment_id' UNION ALL SELECT 'quotes', 'uq_quotes_reservation_terms', 'U:id,space_id,establishment_id,starts_at,ends_at,currency_code' UNION ALL SELECT 'quotes', 'idx_quotes_request_space_establishment', 'N:booking_request_id,space_id,establishment_id' UNION ALL SELECT 'quote_items', 'idx_quote_items_quote_establishment', 'N:quote_id,establishment_id' UNION ALL SELECT 'quote_items', 'idx_quote_items_service_establishment', 'N:establishment_service_id,establishment_id' UNION ALL SELECT 'reservation_statuses', 'uq_reservation_statuses_flags', 'U:id,is_hold,blocks_space' UNION ALL SELECT 'reservations', 'uq_reservations_quote', 'U:quote_id' UNION ALL SELECT 'reservations', 'uq_reservations_id_establishment', 'U:id,establishment_id' UNION ALL SELECT 'reservations', 'uq_reservations_id_venue', 'U:id,venue_id' UNION ALL SELECT 'reservations', 'uq_reservations_id_currency', 'U:id,currency_code' UNION ALL SELECT 'reservations', 'uq_reservations_slot_owner', 'U:id,space_id,establishment_id,status_blocks_space' UNION ALL SELECT 'reservations', 'idx_reservations_status_flags', 'N:status_id,status_is_hold,status_blocks_space' UNION ALL SELECT 'reservations', 'idx_reservations_hold_sweep', 'N:status_is_hold,hold_expires_at' UNION ALL SELECT 'reservations', 'idx_reservations_establishment_venue', 'N:establishment_id,venue_id' UNION ALL SELECT 'reservations', 'idx_reservations_quote_terms', 'N:quote_id,space_id,establishment_id,starts_at,ends_at,currency_code' UNION ALL SELECT 'reservation_services', 'idx_reservation_services_reservation', 'N:reservation_id,establishment_id' UNION ALL SELECT 'reservation_services', 'idx_reservation_services_service', 'N:establishment_service_id,establishment_id' UNION ALL SELECT 'payments', 'uq_payments_id_currency', 'U:id,currency_code' UNION ALL SELECT 'payments', 'idx_payments_reservation_currency', 'N:reservation_id,currency_code' UNION ALL SELECT 'payments', 'idx_payments_method', 'N:payment_method_id,method_requires_card' UNION ALL SELECT 'refunds', 'idx_refunds_payment_currency', 'N:payment_id,currency_code' UNION ALL SELECT 'concert_reservations', 'idx_concert_reservations_concert_venue', 'N:concert_id,venue_id' UNION ALL SELECT 'concert_reservations', 'idx_concert_reservations_reservation_venue', 'N:reservation_id,venue_id' UNION ALL SELECT 'space_occupancy_slots', 'idx_space_occupancy_slots_space', 'N:space_id,establishment_id,is_whole_venue' UNION ALL SELECT 'space_occupancy_slots', 'idx_space_occupancy_slots_mode', 'N:establishment_id,slot_start,is_whole_venue' UNION ALL SELECT 'space_occupancy_slots', 'idx_space_occupancy_slots_block_owner', 'N:block_id,space_id,establishment_id' UNION ALL SELECT 'space_occupancy_slots', 'idx_space_occupancy_slots_reservation_owner', 'N:reservation_id,space_id,establishment_id,reservation_blocks_space' UNION ALL SELECT 'establishment_slot_modes', 'PRIMARY', 'U:establishment_id,slot_start' UNION ALL SELECT 'establishment_slot_modes', 'uq_establishment_slot_modes_mode', 'U:establishment_id,slot_start,is_whole_venue' UNION ALL SELECT 'payment_methods', 'uq_payment_methods_id_card', 'U:id,requires_card' UNION ALL SELECT 'marketplace_cities', 'PRIMARY', 'U:city_id') AS e LEFT JOIN (SELECT table_name AS t, index_name AS n, CONCAT(IF(MIN(non_unique) = 0, 'U', 'N'), ':', GROUP_CONCAT(column_name ORDER BY seq_in_index)) AS s FROM information_schema.statistics WHERE table_schema = DATABASE() GROUP BY table_name, index_name) AS c ON c.t = e.t AND c.n = e.i ORDER BY estado, e.t, e.i;

SELECT 'D03_indices_unicos_de_establishments' AS chequeo, index_name, GROUP_CONCAT(column_name ORDER BY seq_in_index) AS columnas, IF(GROUP_CONCAT(column_name ORDER BY seq_in_index) = 'city_id', 'UNIQUE(city_id): permite un solo establecimiento por ciudad', IF(MIN(seq_in_index) = 1 AND SUBSTRING_INDEX(GROUP_CONCAT(column_name ORDER BY seq_in_index), ',', 1) = 'city_id', 'unico que empieza por city_id', '')) AS observacion FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = 'establishments' AND non_unique = 0 GROUP BY index_name ORDER BY index_name;

SELECT 'D04_indices_heredados_que_la_migracion_debia_quitar' AS chequeo, e.t AS tabla, e.i AS indice, c.s AS definicion_actual FROM (SELECT 'establishments' AS t, 'uq_establishments_city_name_address' AS i UNION ALL SELECT 'space_blocks', 'uq_space_blocks_id_space' UNION ALL SELECT 'quote_items', 'idx_quote_items_quote' UNION ALL SELECT 'quote_items', 'fk_quote_items_establishment_service' UNION ALL SELECT 'reservations', 'uq_reservations_id_space' UNION ALL SELECT 'reservations', 'idx_reservations_quote' UNION ALL SELECT 'reservations', 'idx_reservations_status_hold' UNION ALL SELECT 'reservation_services', 'fk_reservation_services_establishment_service' UNION ALL SELECT 'payments', 'idx_payments_reservation' UNION ALL SELECT 'refunds', 'idx_refunds_payment' UNION ALL SELECT 'space_occupancy_slots', 'idx_space_occupancy_slots_block' UNION ALL SELECT 'space_occupancy_slots', 'idx_space_occupancy_slots_reservation') AS e JOIN (SELECT table_name AS t, index_name AS n, CONCAT(IF(MIN(non_unique) = 0, 'U', 'N'), ':', GROUP_CONCAT(column_name ORDER BY seq_in_index)) AS s FROM information_schema.statistics WHERE table_schema = DATABASE() GROUP BY table_name, index_name) AS c ON c.t = e.t AND c.n = e.i ORDER BY e.t, e.i;

SELECT 'E01_fks_marketplace' AS chequeo, k.table_name, k.constraint_name, GROUP_CONCAT(k.column_name ORDER BY k.ordinal_position) AS columnas, MAX(k.referenced_table_name) AS tabla_ref, GROUP_CONCAT(k.referenced_column_name ORDER BY k.ordinal_position) AS columnas_ref, MAX(r.delete_rule) AS on_delete, MAX(r.update_rule) AS on_update FROM information_schema.key_column_usage k JOIN information_schema.referential_constraints r ON r.constraint_schema = k.constraint_schema AND r.constraint_name = k.constraint_name AND r.table_name = k.table_name WHERE k.constraint_schema = DATABASE() AND k.referenced_table_name IS NOT NULL AND k.table_name IN ('districts', 'cities', 'marketplace_cities', 'organizations', 'organization_members', 'organization_role_permissions', 'establishments', 'establishment_status_history', 'spaces', 'space_features', 'space_blocks', 'service_providers', 'establishment_services', 'booking_requests', 'booking_request_status_history', 'quotes', 'quote_items', 'quote_status_history', 'reservations', 'reservation_status_history', 'reservation_services', 'reservation_agreements', 'agreement_acceptances', 'payments', 'refunds', 'concert_reservations', 'space_occupancy_slots', 'establishment_slot_modes') GROUP BY k.table_name, k.constraint_name ORDER BY k.table_name, k.constraint_name;

SELECT 'E02_fks_esperadas_estado_final' AS chequeo, e.t AS tabla, e.f AS fk, e.d AS esperado, c.s AS real_, CASE WHEN c.s IS NULL THEN 'FALTA' WHEN c.s <> e.d THEN 'DISTINTA' ELSE 'OK' END AS estado FROM (SELECT 'cities' AS t, 'fk_cities_district' AS f, 'district_id>districts(id) RESTRICT/RESTRICT' AS d UNION ALL SELECT 'marketplace_cities', 'fk_marketplace_cities_city', 'city_id>cities(id) RESTRICT/RESTRICT' UNION ALL SELECT 'establishments', 'fk_establishments_city', 'city_id>marketplace_cities(city_id) RESTRICT/RESTRICT' UNION ALL SELECT 'establishments', 'fk_establishments_venue_city', 'venue_id,city_id>venues(id,city_id) RESTRICT/CASCADE' UNION ALL SELECT 'establishments', 'fk_establishments_status', 'status_id>establishment_statuses(id) RESTRICT/RESTRICT' UNION ALL SELECT 'establishments', 'fk_establishments_organization', 'organization_id>organizations(id) RESTRICT/RESTRICT' UNION ALL SELECT 'space_blocks', 'fk_space_blocks_space', 'space_id,establishment_id>spaces(id,establishment_id) CASCADE/RESTRICT' UNION ALL SELECT 'booking_requests', 'fk_booking_requests_space', 'space_id,establishment_id>spaces(id,establishment_id) RESTRICT/RESTRICT' UNION ALL SELECT 'quotes', 'fk_quotes_request', 'booking_request_id,space_id,establishment_id>booking_requests(id,space_id,establishment_id) RESTRICT/RESTRICT' UNION ALL SELECT 'quotes', 'fk_quotes_currency', 'currency_code>currencies(code) RESTRICT/RESTRICT' UNION ALL SELECT 'quote_items', 'fk_quote_items_quote', 'quote_id,establishment_id>quotes(id,establishment_id) CASCADE/RESTRICT' UNION ALL SELECT 'quote_items', 'fk_quote_items_establishment_service', 'establishment_service_id,establishment_id>establishment_services(id,establishment_id) RESTRICT/RESTRICT' UNION ALL SELECT 'reservations', 'fk_reservations_status', 'status_id,status_is_hold,status_blocks_space>reservation_statuses(id,is_hold,blocks_space) RESTRICT/RESTRICT' UNION ALL SELECT 'reservations', 'fk_reservations_quote', 'quote_id,space_id,establishment_id,starts_at,ends_at,currency_code>quotes(id,space_id,establishment_id,starts_at,ends_at,currency_code) RESTRICT/RESTRICT' UNION ALL SELECT 'reservations', 'fk_reservations_establishment_venue', 'establishment_id,venue_id>establishments(id,venue_id) RESTRICT/RESTRICT' UNION ALL SELECT 'reservation_services', 'fk_reservation_services_reservation', 'reservation_id,establishment_id>reservations(id,establishment_id) CASCADE/RESTRICT' UNION ALL SELECT 'reservation_services', 'fk_reservation_services_establishment_service', 'establishment_service_id,establishment_id>establishment_services(id,establishment_id) RESTRICT/RESTRICT' UNION ALL SELECT 'payments', 'fk_payments_reservation', 'reservation_id,currency_code>reservations(id,currency_code) RESTRICT/RESTRICT' UNION ALL SELECT 'payments', 'fk_payments_method', 'payment_method_id,method_requires_card>payment_methods(id,requires_card) RESTRICT/RESTRICT' UNION ALL SELECT 'refunds', 'fk_refunds_payment', 'payment_id,currency_code>payments(id,currency_code) RESTRICT/RESTRICT' UNION ALL SELECT 'concert_reservations', 'fk_concert_reservations_concert', 'concert_id,venue_id>concerts(id,venue_id) CASCADE/RESTRICT' UNION ALL SELECT 'concert_reservations', 'fk_concert_reservations_reservation', 'reservation_id,venue_id>reservations(id,venue_id) RESTRICT/RESTRICT' UNION ALL SELECT 'space_occupancy_slots', 'fk_space_occupancy_slots_space', 'space_id,establishment_id,is_whole_venue>spaces(id,establishment_id,is_whole_venue) RESTRICT/RESTRICT' UNION ALL SELECT 'space_occupancy_slots', 'fk_space_occupancy_slots_mode', 'establishment_id,slot_start,is_whole_venue>establishment_slot_modes(establishment_id,slot_start,is_whole_venue) RESTRICT/RESTRICT' UNION ALL SELECT 'space_occupancy_slots', 'fk_space_occupancy_slots_block', 'block_id,space_id,establishment_id>space_blocks(id,space_id,establishment_id) RESTRICT/RESTRICT' UNION ALL SELECT 'space_occupancy_slots', 'fk_space_occupancy_slots_reservation', 'reservation_id,space_id,establishment_id,reservation_blocks_space>reservations(id,space_id,establishment_id,status_blocks_space) RESTRICT/RESTRICT' UNION ALL SELECT 'establishment_slot_modes', 'fk_establishment_slot_modes_establishment', 'establishment_id>establishments(id) RESTRICT/RESTRICT') AS e LEFT JOIN (SELECT k.table_name AS t, k.constraint_name AS n, CONCAT(GROUP_CONCAT(k.column_name ORDER BY k.ordinal_position), '>', MAX(k.referenced_table_name), '(', GROUP_CONCAT(k.referenced_column_name ORDER BY k.ordinal_position), ') ', MAX(REPLACE(r.delete_rule, 'NO ACTION', 'RESTRICT')), '/', MAX(REPLACE(r.update_rule, 'NO ACTION', 'RESTRICT'))) AS s FROM information_schema.key_column_usage k JOIN information_schema.referential_constraints r ON r.constraint_schema = k.constraint_schema AND r.constraint_name = k.constraint_name AND r.table_name = k.table_name WHERE k.constraint_schema = DATABASE() AND k.referenced_table_name IS NOT NULL GROUP BY k.table_name, k.constraint_name) AS c ON c.t = e.t AND c.n = e.f ORDER BY estado, e.t, e.f;

SELECT 'E03_fks_heredadas_que_debian_quitarse' AS chequeo, table_name, constraint_name FROM information_schema.table_constraints WHERE constraint_schema = DATABASE() AND constraint_type = 'FOREIGN KEY' AND ((table_name = 'establishments' AND constraint_name = 'fk_establishments_venue') OR (table_name = 'reservations' AND constraint_name = 'fk_reservations_space')) ORDER BY table_name;

SELECT 'F01_checks_marketplace' AS chequeo, tc.table_name, tc.constraint_name, tc.enforced, cc.check_clause FROM information_schema.table_constraints tc JOIN information_schema.check_constraints cc ON cc.constraint_schema = tc.constraint_schema AND cc.constraint_name = tc.constraint_name WHERE tc.constraint_schema = DATABASE() AND tc.constraint_type = 'CHECK' AND tc.table_name IN ('organizations', 'establishments', 'spaces', 'space_blocks', 'establishment_services', 'booking_requests', 'quotes', 'quote_items', 'reservation_statuses', 'reservations', 'reservation_services', 'reservation_agreements', 'payments', 'refunds', 'space_occupancy_slots', 'establishment_slot_modes', 'venues') ORDER BY tc.table_name, tc.constraint_name;

SELECT 'F02_checks_esperados' AS chequeo, e.t AS tabla, e.k AS check_esperado, x.enforced, CASE WHEN x.check_clause IS NULL THEN 'FALTA' WHEN x.enforced <> 'YES' THEN 'NO_APLICADO' WHEN x.check_clause NOT LIKE CONCAT('%', e.w1, '%') OR x.check_clause NOT LIKE CONCAT('%', e.w2, '%') THEN 'CLAUSULA_INESPERADA' ELSE 'OK' END AS estado, x.check_clause FROM (SELECT 'reservation_statuses' AS t, 'chk_reservation_statuses_hold_blocks' AS k, 'is_hold' AS w1, 'blocks_space' AS w2 UNION ALL SELECT 'reservations', 'chk_reservations_hold_flag', 'status_is_hold', 'hold_expires_at' UNION ALL SELECT 'reservations', 'chk_reservations_hold_max_15_minutes', 'hold_expires_at', 'created_at' UNION ALL SELECT 'reservations', 'chk_reservations_range', 'ends_at', 'starts_at' UNION ALL SELECT 'reservations', 'chk_reservations_alignment', 'starts_at', 'ends_at' UNION ALL SELECT 'reservations', 'chk_reservations_max_duration', 'starts_at', '10080' UNION ALL SELECT 'payments', 'chk_payments_method_card', 'method_requires_card', 'card_last4' UNION ALL SELECT 'space_occupancy_slots', 'chk_space_occupancy_slots_single_owner', 'reservation_blocks_space', 'block_id' UNION ALL SELECT 'space_occupancy_slots', 'chk_space_occupancy_slots_alignment', 'slot_start', '15' UNION ALL SELECT 'establishment_slot_modes', 'chk_establishment_slot_modes_alignment', 'slot_start', '15' UNION ALL SELECT 'establishments', 'chk_establishments_coordinates', 'latitude', 'longitude' UNION ALL SELECT 'space_blocks', 'chk_space_blocks_range', 'ends_at', 'starts_at' UNION ALL SELECT 'spaces', 'chk_spaces_capacity', 'capacity', '0') AS e LEFT JOIN (SELECT tc.table_name, tc.constraint_name, tc.enforced, cc.check_clause FROM information_schema.table_constraints tc JOIN information_schema.check_constraints cc ON cc.constraint_schema = tc.constraint_schema AND cc.constraint_name = tc.constraint_name WHERE tc.constraint_schema = DATABASE() AND tc.constraint_type = 'CHECK') AS x ON x.table_name = e.t AND x.constraint_name = e.k ORDER BY estado, e.t, e.k;

SELECT 'F03_check_heredado_que_debia_quitarse' AS chequeo, COUNT(*) AS presente FROM information_schema.table_constraints WHERE constraint_schema = DATABASE() AND table_name = 'payments' AND constraint_name = 'chk_payments_card' AND constraint_type = 'CHECK';

SELECT 'G01_objetos_finales_faltantes' AS chequeo, e.t AS tabla, e.o AS objeto FROM (SELECT 'venues' AS t, 'uq_venues_id_city' AS o UNION ALL SELECT 'concerts', 'uq_concerts_id_venue' UNION ALL SELECT 'establishments', 'uq_establishments_id_venue' UNION ALL SELECT 'spaces', 'uq_spaces_establishment_whole_venue' UNION ALL SELECT 'spaces', 'uq_spaces_id_establishment' UNION ALL SELECT 'spaces', 'uq_spaces_id_establishment_whole' UNION ALL SELECT 'space_blocks', 'uq_space_blocks_id_space_establishment' UNION ALL SELECT 'establishment_services', 'uq_establishment_services_id_establishment' UNION ALL SELECT 'booking_requests', 'uq_booking_requests_id_space_establishment' UNION ALL SELECT 'quotes', 'uq_quotes_id_establishment' UNION ALL SELECT 'quotes', 'uq_quotes_reservation_terms' UNION ALL SELECT 'reservation_statuses', 'uq_reservation_statuses_flags' UNION ALL SELECT 'reservations', 'uq_reservations_quote' UNION ALL SELECT 'reservations', 'uq_reservations_id_establishment' UNION ALL SELECT 'reservations', 'uq_reservations_id_venue' UNION ALL SELECT 'reservations', 'uq_reservations_id_currency' UNION ALL SELECT 'reservations', 'uq_reservations_slot_owner' UNION ALL SELECT 'payments', 'uq_payments_id_currency' UNION ALL SELECT 'establishments', 'fk_establishments_venue_city' UNION ALL SELECT 'space_blocks', 'fk_space_blocks_space' UNION ALL SELECT 'booking_requests', 'fk_booking_requests_space' UNION ALL SELECT 'quotes', 'fk_quotes_request' UNION ALL SELECT 'quotes', 'fk_quotes_currency' UNION ALL SELECT 'quote_items', 'fk_quote_items_quote' UNION ALL SELECT 'quote_items', 'fk_quote_items_establishment_service' UNION ALL SELECT 'reservations', 'fk_reservations_status' UNION ALL SELECT 'reservations', 'fk_reservations_quote' UNION ALL SELECT 'reservations', 'fk_reservations_establishment_venue' UNION ALL SELECT 'reservation_services', 'fk_reservation_services_reservation' UNION ALL SELECT 'reservation_services', 'fk_reservation_services_establishment_service' UNION ALL SELECT 'payments', 'fk_payments_reservation' UNION ALL SELECT 'payments', 'fk_payments_method' UNION ALL SELECT 'refunds', 'fk_refunds_payment' UNION ALL SELECT 'concert_reservations', 'fk_concert_reservations_concert' UNION ALL SELECT 'concert_reservations', 'fk_concert_reservations_reservation' UNION ALL SELECT 'space_occupancy_slots', 'fk_space_occupancy_slots_space' UNION ALL SELECT 'space_occupancy_slots', 'fk_space_occupancy_slots_mode' UNION ALL SELECT 'space_occupancy_slots', 'fk_space_occupancy_slots_block' UNION ALL SELECT 'space_occupancy_slots', 'fk_space_occupancy_slots_reservation' UNION ALL SELECT 'reservation_statuses', 'chk_reservation_statuses_hold_blocks' UNION ALL SELECT 'reservations', 'chk_reservations_hold_flag' UNION ALL SELECT 'payments', 'chk_payments_method_card' UNION ALL SELECT 'space_occupancy_slots', 'chk_space_occupancy_slots_single_owner') AS e WHERE NOT EXISTS (SELECT 1 FROM information_schema.statistics s WHERE s.table_schema = DATABASE() AND s.table_name = e.t AND s.index_name = e.o) AND NOT EXISTS (SELECT 1 FROM information_schema.table_constraints c WHERE c.constraint_schema = DATABASE() AND c.table_name = e.t AND c.constraint_name = e.o) ORDER BY e.t, e.o;

SELECT 'G02_resumen_estado_migracion' AS chequeo, (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name IN ('districts', 'marketplace_cities', 'organizations', 'organization_roles', 'permissions', 'organization_role_permissions', 'organization_members', 'establishment_statuses', 'establishments', 'establishment_status_history', 'space_types', 'spaces', 'features', 'space_features', 'space_block_types', 'space_blocks', 'services', 'service_providers', 'establishment_services', 'booking_request_statuses', 'booking_requests', 'booking_request_status_history', 'quote_statuses', 'quote_concepts', 'quotes', 'quote_items', 'quote_status_history', 'reservation_statuses', 'reservations', 'reservation_status_history', 'reservation_services', 'reservation_agreements', 'agreement_acceptances', 'space_occupancy_slots', 'card_brands', 'payment_statuses', 'refund_statuses', 'payments', 'refunds', 'concert_reservations', 'currencies', 'payment_methods', 'establishment_slot_modes')) AS tablas_marketplace_de_43, (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'establishments' AND column_name IN ('name', 'address')) AS establishments_name_address_restantes, (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND is_nullable = 'YES' AND (table_name, column_name) IN (('space_blocks', 'establishment_id'), ('booking_requests', 'establishment_id'), ('quotes', 'space_id'), ('quotes', 'establishment_id'), ('quote_items', 'establishment_id'), ('reservations', 'establishment_id'), ('reservations', 'venue_id'), ('reservations', 'currency_code'), ('reservations', 'status_is_hold'), ('reservations', 'status_blocks_space'), ('reservation_services', 'establishment_id'), ('payments', 'currency_code'), ('payments', 'payment_method_id'), ('payments', 'method_requires_card'), ('refunds', 'currency_code'), ('concert_reservations', 'venue_id'), ('space_occupancy_slots', 'establishment_id'), ('space_occupancy_slots', 'is_whole_venue'), ('establishments', 'venue_id'))) AS columnas_nullables_indebidas, (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'cities' AND column_name = 'district_id') AS cities_district_id, (SELECT COUNT(*) FROM information_schema.table_constraints WHERE constraint_schema = DATABASE() AND constraint_name = 'fk_space_occupancy_slots_reservation' AND constraint_type = 'FOREIGN KEY') AS fk_slots_reservation_presente, (SELECT COUNT(*) FROM information_schema.key_column_usage WHERE constraint_schema = DATABASE() AND table_name = 'space_occupancy_slots' AND constraint_name = 'fk_space_occupancy_slots_reservation' AND referenced_table_name IS NOT NULL) AS fk_slots_reservation_columnas, (SELECT COUNT(*) FROM information_schema.key_column_usage WHERE constraint_schema = DATABASE() AND table_name = 'reservations' AND constraint_name = 'fk_reservations_status' AND referenced_table_name IS NOT NULL) AS fk_reservations_status_columnas, (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = 'establishments' AND index_name = 'uq_establishments_city_name_address') AS uq_city_name_address_columnas_restantes;

SELECT 'H01_venues_y_establecimientos_por_ciudad_marketplace' AS chequeo, mc.city_id, c.name AS ciudad, (SELECT COUNT(*) FROM venues v WHERE v.city_id = mc.city_id) AS venues, (SELECT COUNT(*) FROM establishments e WHERE e.city_id = mc.city_id) AS establecimientos, (SELECT COUNT(*) FROM venues v WHERE v.city_id = mc.city_id AND NOT EXISTS (SELECT 1 FROM establishments e WHERE e.venue_id = v.id)) AS venues_sin_establecimiento FROM marketplace_cities mc JOIN cities c ON c.id = mc.city_id ORDER BY c.name;

SELECT 'H02_veredicto_unicidad_por_ciudad' AS chequeo, (SELECT COUNT(*) FROM (SELECT index_name FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = 'establishments' AND non_unique = 0 GROUP BY index_name HAVING GROUP_CONCAT(column_name ORDER BY seq_in_index) = 'city_id') AS u) AS indices_unique_solo_city_id, (SELECT COUNT(*) FROM (SELECT city_id FROM establishments GROUP BY city_id HAVING COUNT(*) > 1) AS d) AS ciudades_con_varios_establecimientos, (SELECT COUNT(*) FROM venues v JOIN marketplace_cities mc ON mc.city_id = v.city_id WHERE NOT EXISTS (SELECT 1 FROM establishments e WHERE e.venue_id = v.id)) AS venues_marketplace_sin_establecimiento, (SELECT COUNT(*) FROM (SELECT v.city_id FROM venues v JOIN marketplace_cities mc ON mc.city_id = v.city_id GROUP BY v.city_id HAVING COUNT(*) > 1) AS m) AS ciudades_marketplace_con_varios_venues;

SELECT 'I01_banderas_reservation_statuses' AS chequeo, e.code, rs.id, rs.name, rs.is_hold, rs.blocks_space, e.h AS is_hold_esperado, e.b AS blocks_space_esperado, CASE WHEN rs.id IS NULL THEN 'FALTA' WHEN rs.is_hold <> e.h OR rs.blocks_space <> e.b THEN 'BANDERAS_INCORRECTAS' ELSE 'OK' END AS estado FROM (SELECT 1 AS o, 'HOLD' AS code, 1 AS h, 1 AS b UNION ALL SELECT 2, 'CONFIRMED', 0, 1 UNION ALL SELECT 3, 'COMPLETED', 0, 1 UNION ALL SELECT 4, 'CANCELLED', 0, 0 UNION ALL SELECT 5, 'EXPIRED', 0, 0) AS e LEFT JOIN reservation_statuses rs ON rs.code = e.code UNION ALL SELECT 'I01_banderas_reservation_statuses', rs.code, rs.id, rs.name, rs.is_hold, rs.blocks_space, NULL, NULL, 'CODIGO_NO_PREVISTO' FROM reservation_statuses rs WHERE rs.code NOT IN ('HOLD', 'CONFIRMED', 'COMPLETED', 'CANCELLED', 'EXPIRED');

SELECT 'I02_reservas_por_estado' AS chequeo, x.code, x.is_hold, x.blocks_space, COUNT(r.id) AS reservas, SUM(r.hold_expires_at IS NOT NULL) AS con_hold_expires_at FROM reservation_statuses x LEFT JOIN reservations r ON r.status_id = x.id GROUP BY x.id, x.code, x.is_hold, x.blocks_space ORDER BY x.id;

SELECT 'I03_reservas_con_banderas_distintas_a_su_estado' AS chequeo, r.id, x.code, r.status_is_hold, x.is_hold, r.status_blocks_space, x.blocks_space FROM reservations r JOIN reservation_statuses x ON x.id = r.status_id WHERE NOT (r.status_is_hold <=> x.is_hold) OR NOT (r.status_blocks_space <=> x.blocks_space) ORDER BY r.id;

SELECT 'J01_reservas_bloqueantes_sin_ocupacion' AS chequeo, r.id, x.code, r.space_id, r.establishment_id, r.starts_at, r.ends_at FROM reservations r JOIN reservation_statuses x ON x.id = r.status_id WHERE x.blocks_space = 1 AND NOT EXISTS (SELECT 1 FROM space_occupancy_slots o WHERE o.reservation_id = r.id) ORDER BY r.id;

SELECT 'J02_reservas_bloqueantes_con_cobertura_incompleta' AS chequeo, r.id, x.code, r.starts_at, r.ends_at, TIMESTAMPDIFF(MINUTE, r.starts_at, r.ends_at) DIV 15 AS tramos_esperados, COUNT(o.slot_start) AS tramos_reales FROM reservations r JOIN reservation_statuses x ON x.id = r.status_id LEFT JOIN space_occupancy_slots o ON o.reservation_id = r.id AND o.space_id = r.space_id AND o.slot_start >= r.starts_at AND o.slot_start < r.ends_at WHERE x.blocks_space = 1 GROUP BY r.id, x.code, r.starts_at, r.ends_at HAVING tramos_reales <> tramos_esperados ORDER BY r.id;

SELECT 'J03_tramos_fuera_del_rango_o_espacio_de_su_reserva' AS chequeo, o.space_id, o.slot_start, o.reservation_id, r.space_id AS espacio_reserva, r.starts_at, r.ends_at FROM space_occupancy_slots o JOIN reservations r ON r.id = o.reservation_id WHERE o.space_id <> r.space_id OR o.establishment_id <> r.establishment_id OR o.slot_start < r.starts_at OR o.slot_start >= r.ends_at ORDER BY o.reservation_id, o.slot_start;

SELECT 'J04_ocupaciones_huerfanas' AS chequeo, (SELECT COUNT(*) FROM space_occupancy_slots o WHERE o.reservation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM reservations r WHERE r.id = o.reservation_id)) AS sin_reserva, (SELECT COUNT(*) FROM space_occupancy_slots o WHERE o.block_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM space_blocks b WHERE b.id = o.block_id)) AS sin_bloqueo, (SELECT COUNT(*) FROM space_occupancy_slots o WHERE NOT EXISTS (SELECT 1 FROM spaces s WHERE s.id = o.space_id)) AS sin_espacio, (SELECT COUNT(*) FROM space_occupancy_slots o WHERE NOT EXISTS (SELECT 1 FROM establishment_slot_modes m WHERE m.establishment_id = o.establishment_id AND m.slot_start = o.slot_start AND m.is_whole_venue = o.is_whole_venue)) AS sin_modo, (SELECT COUNT(*) FROM space_occupancy_slots o WHERE (o.block_id IS NULL) = (o.reservation_id IS NULL)) AS sin_dueno_o_doble_dueno, (SELECT COUNT(*) FROM space_occupancy_slots) AS total_tramos;

SELECT 'J05_tramos_de_reservas_que_no_bloquean' AS chequeo, o.reservation_id, x.code, o.reservation_blocks_space, r.status_blocks_space, COUNT(*) AS tramos FROM space_occupancy_slots o JOIN reservations r ON r.id = o.reservation_id JOIN reservation_statuses x ON x.id = r.status_id WHERE x.blocks_space = 0 OR NOT (o.reservation_blocks_space <=> 1) OR NOT (r.status_blocks_space <=> 1) GROUP BY o.reservation_id, x.code, o.reservation_blocks_space, r.status_blocks_space ORDER BY o.reservation_id;

SELECT 'J06_tramos_con_establecimiento_o_modalidad_distintos_al_espacio' AS chequeo, o.space_id, o.slot_start, o.establishment_id, s.establishment_id AS est_espacio, o.is_whole_venue, s.is_whole_venue AS whole_espacio FROM space_occupancy_slots o JOIN spaces s ON s.id = o.space_id WHERE NOT (o.establishment_id <=> s.establishment_id) OR NOT (o.is_whole_venue <=> s.is_whole_venue) ORDER BY o.space_id, o.slot_start;

SELECT 'J07_bloqueos_con_cobertura_incompleta' AS chequeo, b.id, b.space_id, b.starts_at, b.ends_at, TIMESTAMPDIFF(MINUTE, b.starts_at, b.ends_at) DIV 15 AS tramos_esperados, COUNT(o.slot_start) AS tramos_reales FROM space_blocks b LEFT JOIN space_occupancy_slots o ON o.block_id = b.id AND o.space_id = b.space_id AND o.slot_start >= b.starts_at AND o.slot_start < b.ends_at GROUP BY b.id, b.space_id, b.starts_at, b.ends_at HAVING tramos_reales <> tramos_esperados ORDER BY b.id;

SELECT 'J08_rangos_invalidos' AS chequeo, 'space_blocks' AS tabla, SUM(ends_at <= starts_at) AS fin_no_posterior, SUM(MINUTE(starts_at) % 15 <> 0 OR SECOND(starts_at) <> 0 OR MINUTE(ends_at) % 15 <> 0 OR SECOND(ends_at) <> 0) AS desalineados, SUM(TIMESTAMPDIFF(MINUTE, starts_at, ends_at) > 10080) AS mas_de_7_dias, COUNT(*) AS total FROM space_blocks UNION ALL SELECT 'J08_rangos_invalidos', 'booking_requests', SUM(ends_at <= starts_at), SUM(MINUTE(starts_at) % 15 <> 0 OR SECOND(starts_at) <> 0 OR MINUTE(ends_at) % 15 <> 0 OR SECOND(ends_at) <> 0), SUM(TIMESTAMPDIFF(MINUTE, starts_at, ends_at) > 10080), COUNT(*) FROM booking_requests UNION ALL SELECT 'J08_rangos_invalidos', 'quotes', SUM(ends_at <= starts_at), SUM(MINUTE(starts_at) % 15 <> 0 OR SECOND(starts_at) <> 0 OR MINUTE(ends_at) % 15 <> 0 OR SECOND(ends_at) <> 0), SUM(TIMESTAMPDIFF(MINUTE, starts_at, ends_at) > 10080), COUNT(*) FROM quotes UNION ALL SELECT 'J08_rangos_invalidos', 'reservations', SUM(ends_at <= starts_at), SUM(MINUTE(starts_at) % 15 <> 0 OR SECOND(starts_at) <> 0 OR MINUTE(ends_at) % 15 <> 0 OR SECOND(ends_at) <> 0), SUM(TIMESTAMPDIFF(MINUTE, starts_at, ends_at) > 10080), COUNT(*) FROM reservations UNION ALL SELECT 'J08_rangos_invalidos', 'space_occupancy_slots', NULL, SUM(MINUTE(slot_start) % 15 <> 0 OR SECOND(slot_start) <> 0), NULL, COUNT(*) FROM space_occupancy_slots UNION ALL SELECT 'J08_rangos_invalidos', 'establishment_slot_modes', NULL, SUM(MINUTE(slot_start) % 15 <> 0 OR SECOND(slot_start) <> 0), NULL, COUNT(*) FROM establishment_slot_modes;

SELECT 'J09_conflicto_reservas_bloqueantes_mismo_espacio' AS chequeo, r1.space_id, r1.id AS reserva_a, r2.id AS reserva_b, r1.starts_at AS a_inicio, r1.ends_at AS a_fin, r2.starts_at AS b_inicio, r2.ends_at AS b_fin FROM reservations r1 JOIN reservations r2 ON r2.space_id = r1.space_id AND r2.id > r1.id AND r2.starts_at < r1.ends_at AND r1.starts_at < r2.ends_at JOIN reservation_statuses x1 ON x1.id = r1.status_id AND x1.blocks_space = 1 JOIN reservation_statuses x2 ON x2.id = r2.status_id AND x2.blocks_space = 1 ORDER BY r1.space_id, r1.id;

SELECT 'J10_conflicto_reserva_bloqueante_vs_bloqueo' AS chequeo, r.space_id, r.id AS reserva, b.id AS bloqueo, r.starts_at, r.ends_at, b.starts_at AS bloqueo_inicio, b.ends_at AS bloqueo_fin FROM reservations r JOIN reservation_statuses x ON x.id = r.status_id AND x.blocks_space = 1 JOIN space_blocks b ON b.space_id = r.space_id AND b.starts_at < r.ends_at AND r.starts_at < b.ends_at ORDER BY r.space_id, r.id;

SELECT 'J11_conflicto_modalidad_completo_vs_parcial' AS chequeo, sw.establishment_id, rw.id AS reserva_completa, rp.id AS reserva_parcial, rw.starts_at AS completa_inicio, rw.ends_at AS completa_fin, rp.starts_at AS parcial_inicio, rp.ends_at AS parcial_fin FROM reservations rw JOIN spaces sw ON sw.id = rw.space_id AND sw.is_whole_venue = 1 JOIN reservation_statuses xw ON xw.id = rw.status_id AND xw.blocks_space = 1 JOIN reservations rp ON rp.establishment_id = rw.establishment_id AND rp.id <> rw.id AND rp.starts_at < rw.ends_at AND rw.starts_at < rp.ends_at JOIN spaces sp ON sp.id = rp.space_id AND sp.is_whole_venue = 0 JOIN reservation_statuses xp ON xp.id = rp.status_id AND xp.blocks_space = 1 ORDER BY sw.establishment_id, rw.id;

SELECT 'J12_tramos_con_modalidades_mezcladas' AS chequeo, o.establishment_id, o.slot_start, COUNT(*) AS tramos, COUNT(DISTINCT o.is_whole_venue) AS modalidades FROM space_occupancy_slots o GROUP BY o.establishment_id, o.slot_start HAVING COUNT(DISTINCT o.is_whole_venue) > 1 ORDER BY o.establishment_id, o.slot_start;

SELECT 'J13_duplicados_estructurales' AS chequeo, (SELECT COUNT(*) FROM (SELECT quote_id FROM reservations GROUP BY quote_id HAVING COUNT(*) > 1) AS a) AS cotizaciones_con_varias_reservas, (SELECT COUNT(*) FROM (SELECT venue_id FROM establishments WHERE venue_id IS NOT NULL GROUP BY venue_id HAVING COUNT(*) > 1) AS b) AS venues_con_varios_establecimientos, (SELECT COUNT(*) FROM (SELECT establishment_id FROM spaces WHERE is_whole_venue = 1 GROUP BY establishment_id HAVING COUNT(*) > 1) AS c) AS establecimientos_con_varios_espacios_completos, (SELECT COUNT(*) FROM (SELECT establishment_id, name FROM spaces GROUP BY establishment_id, name HAVING COUNT(*) > 1) AS d) AS espacios_con_nombre_repetido, (SELECT COUNT(*) FROM (SELECT space_id, slot_start FROM space_occupancy_slots GROUP BY space_id, slot_start HAVING COUNT(*) > 1) AS e) AS tramos_duplicados, (SELECT COUNT(*) FROM (SELECT establishment_id, slot_start FROM establishment_slot_modes GROUP BY establishment_id, slot_start HAVING COUNT(*) > 1) AS f) AS modos_duplicados;

SELECT 'J14_consistencia_derivada_marketplace' AS chequeo, (SELECT COUNT(*) FROM space_blocks b JOIN spaces s ON s.id = b.space_id WHERE NOT (b.establishment_id <=> s.establishment_id)) AS bloqueos_est_distinto, (SELECT COUNT(*) FROM booking_requests b JOIN spaces s ON s.id = b.space_id WHERE NOT (b.establishment_id <=> s.establishment_id)) AS solicitudes_est_distinto, (SELECT COUNT(*) FROM quotes q JOIN booking_requests b ON b.id = q.booking_request_id WHERE NOT (q.space_id <=> b.space_id) OR NOT (q.establishment_id <=> b.establishment_id)) AS cotizaciones_distintas_a_solicitud, (SELECT COUNT(*) FROM quote_items i JOIN quotes q ON q.id = i.quote_id WHERE NOT (i.establishment_id <=> q.establishment_id)) AS items_est_distinto, (SELECT COUNT(*) FROM reservations r JOIN quotes q ON q.id = r.quote_id WHERE r.space_id <> q.space_id OR r.starts_at <> q.starts_at OR r.ends_at <> q.ends_at OR NOT (r.currency_code <=> q.currency_code)) AS reservas_distintas_a_cotizacion, (SELECT COUNT(*) FROM reservations r JOIN establishments e ON e.id = r.establishment_id WHERE NOT (r.venue_id <=> e.venue_id)) AS reservas_venue_distinto, (SELECT COUNT(*) FROM payments p JOIN reservations r ON r.id = p.reservation_id WHERE NOT (p.currency_code <=> r.currency_code)) AS pagos_moneda_distinta, (SELECT COUNT(*) FROM refunds f JOIN payments p ON p.id = f.payment_id WHERE NOT (f.currency_code <=> p.currency_code)) AS devoluciones_moneda_distinta, (SELECT COUNT(*) FROM concert_reservations cr JOIN concerts c ON c.id = cr.concert_id JOIN reservations r ON r.id = cr.reservation_id WHERE c.venue_id <> r.venue_id OR NOT (cr.venue_id <=> r.venue_id)) AS conciertos_venue_distinto;

SELECT 'K01_resumen_modos_de_tramo' AS chequeo, COUNT(*) AS modos_totales, SUM(NOT EXISTS (SELECT 1 FROM space_occupancy_slots o WHERE o.establishment_id = m.establishment_id AND o.slot_start = m.slot_start AND o.is_whole_venue = m.is_whole_venue)) AS modos_sin_ocupacion_obsoletos, SUM(m.slot_start < UTC_TIMESTAMP()) AS modos_pasados, SUM(m.slot_start >= UTC_TIMESTAMP() AND NOT EXISTS (SELECT 1 FROM space_occupancy_slots o WHERE o.establishment_id = m.establishment_id AND o.slot_start = m.slot_start AND o.is_whole_venue = m.is_whole_venue)) AS modos_obsoletos_futuros_que_bloquean_la_otra_modalidad, SUM(NOT EXISTS (SELECT 1 FROM spaces s WHERE s.establishment_id = m.establishment_id AND s.is_whole_venue = m.is_whole_venue)) AS modos_sin_espacio_de_esa_modalidad FROM establishment_slot_modes m;

SELECT 'K02_detalle_modos_obsoletos' AS chequeo, m.establishment_id, m.slot_start, m.is_whole_venue, IF(m.slot_start >= UTC_TIMESTAMP(), 'FUTURO', 'PASADO') AS momento FROM establishment_slot_modes m WHERE NOT EXISTS (SELECT 1 FROM space_occupancy_slots o WHERE o.establishment_id = m.establishment_id AND o.slot_start = m.slot_start AND o.is_whole_venue = m.is_whole_venue) ORDER BY m.establishment_id, m.slot_start LIMIT 500;

SELECT 'L01_provincias_candidatas' AS chequeo, p.id, p.name, (SELECT COUNT(*) FROM cities c WHERE c.province_id = p.id) AS ciudades, (SELECT COUNT(*) FROM districts d WHERE d.province_id = p.id) AS partidos FROM provinces p WHERE p.name LIKE '%buenos%' OR p.name LIKE '%bs%as%' OR p.name LIKE '%pba%' ORDER BY p.id;

SELECT 'L02_partidos' AS chequeo, d.id, d.name AS partido, d.province_id, p.name AS provincia, (SELECT COUNT(*) FROM cities c WHERE c.district_id = d.id) AS ciudades FROM districts d JOIN provinces p ON p.id = d.province_id ORDER BY d.id;

SELECT 'L03_ciudades_general_pueyrredon_y_similares' AS chequeo, c.id, c.name AS ciudad, p.name AS provincia, d.name AS partido, IF(mc.city_id IS NULL, 'NO', 'SI') AS en_marketplace, (SELECT COUNT(*) FROM venues v WHERE v.city_id = c.id) AS venues FROM cities c JOIN provinces p ON p.id = c.province_id LEFT JOIN districts d ON d.id = c.district_id LEFT JOIN marketplace_cities mc ON mc.city_id = c.id WHERE c.district_id IS NOT NULL OR mc.city_id IS NOT NULL OR c.name LIKE '%plata%' OR c.name LIKE '%batan%' OR c.name LIKE '%padres%' OR c.name LIKE '%chapadmalal%' OR c.name LIKE '%pueyrred%' OR c.name LIKE '%mdq%' ORDER BY c.name, c.id;

SELECT 'L04_ciudades_esperadas_del_marketplace' AS chequeo, e.n AS ciudad_esperada, COUNT(c.id) AS coincidencias_en_buenos_aires, MIN(c.id) AS city_id, MAX(d.name) AS partido, SUM(mc.city_id IS NOT NULL) AS en_marketplace, CASE WHEN COUNT(c.id) = 0 THEN 'FALTA_CIUDAD' WHEN COUNT(c.id) > 1 THEN 'DUPLICADA' WHEN MAX(d.name) IS NULL THEN 'SIN_PARTIDO' WHEN MAX(d.name) <> 'General Pueyrredón' THEN 'PARTIDO_INCORRECTO' WHEN SUM(mc.city_id IS NOT NULL) = 0 THEN 'FUERA_DEL_MARKETPLACE' ELSE 'OK' END AS estado FROM (SELECT 'Mar del Plata' AS n UNION ALL SELECT 'Batán' UNION ALL SELECT 'Sierra de los Padres' UNION ALL SELECT 'Chapadmalal') AS e LEFT JOIN (cities c JOIN provinces p ON p.id = c.province_id AND p.name = 'Buenos Aires') ON c.name = e.n LEFT JOIN districts d ON d.id = c.district_id LEFT JOIN marketplace_cities mc ON mc.city_id = c.id GROUP BY e.n ORDER BY e.n;

SELECT 'L05_marketplace_fuera_de_general_pueyrredon' AS chequeo, mc.city_id, c.name AS ciudad, p.name AS provincia, d.name AS partido FROM marketplace_cities mc LEFT JOIN cities c ON c.id = mc.city_id LEFT JOIN provinces p ON p.id = c.province_id LEFT JOIN districts d ON d.id = c.district_id WHERE c.id IS NULL OR d.id IS NULL OR d.name <> 'General Pueyrredón' OR p.name <> 'Buenos Aires' OR d.province_id <> c.province_id ORDER BY mc.city_id;

SELECT 'L06_ciudades_con_partido_de_otra_provincia' AS chequeo, c.id, c.name, c.province_id, d.id AS district_id, d.province_id AS provincia_del_partido FROM cities c JOIN districts d ON d.id = c.district_id WHERE d.province_id <> c.province_id ORDER BY c.id;

SELECT 'L07_venues_en_ciudades_parecidas_fuera_del_marketplace' AS chequeo, c.id AS city_id, c.name AS ciudad, p.name AS provincia, COUNT(v.id) AS venues FROM cities c JOIN provinces p ON p.id = c.province_id JOIN venues v ON v.city_id = c.id WHERE NOT EXISTS (SELECT 1 FROM marketplace_cities mc WHERE mc.city_id = c.id) AND (c.name LIKE '%plata%' OR c.name LIKE '%batan%' OR c.name LIKE '%padres%' OR c.name LIKE '%chapadmalal%' OR c.name LIKE '%pueyrred%' OR c.name LIKE '%mdq%') GROUP BY c.id, c.name, p.name ORDER BY c.name;

SELECT 'M01_venues_del_marketplace_sin_establecimiento' AS chequeo, v.id, v.city_id, c.name AS ciudad, v.name, v.address, v.capacity, v.created_at FROM venues v JOIN marketplace_cities mc ON mc.city_id = v.city_id JOIN cities c ON c.id = v.city_id WHERE NOT EXISTS (SELECT 1 FROM establishments e WHERE e.venue_id = v.id) ORDER BY v.id;

SELECT 'M02_establecimientos_y_su_venue' AS chequeo, e.id, e.venue_id, e.city_id, v.city_id AS city_venue, c.name AS ciudad, v.name AS venue, v.address, s.code AS estado, e.organization_id, e.created_at, CASE WHEN v.id IS NULL THEN 'SIN_VENUE' WHEN v.city_id <> e.city_id THEN 'CIUDAD_DISTINTA' ELSE 'OK' END AS verificacion FROM establishments e LEFT JOIN venues v ON v.id = e.venue_id LEFT JOIN cities c ON c.id = e.city_id LEFT JOIN establishment_statuses s ON s.id = e.status_id ORDER BY e.id;

SELECT 'M03_venues_duplicados_normalizados' AS chequeo, v.city_id, LOWER(TRIM(v.name)) AS nombre_normalizado, COUNT(*) AS cantidad, GROUP_CONCAT(v.id ORDER BY v.id) AS venue_ids, GROUP_CONCAT(DISTINCT LOWER(TRIM(v.address)) SEPARATOR ' / ') AS direcciones, IF(EXISTS (SELECT 1 FROM marketplace_cities mc WHERE mc.city_id = v.city_id), 'SI', 'NO') AS en_marketplace FROM venues v GROUP BY v.city_id, LOWER(TRIM(v.name)) HAVING COUNT(*) > 1 ORDER BY v.city_id, nombre_normalizado;

SELECT 'M04_venues_misma_direccion_en_la_ciudad' AS chequeo, v.city_id, LOWER(TRIM(REPLACE(v.address, '  ', ' '))) AS direccion_normalizada, COUNT(*) AS cantidad, GROUP_CONCAT(v.id ORDER BY v.id) AS venue_ids, GROUP_CONCAT(v.name ORDER BY v.id SEPARATOR ' / ') AS nombres FROM venues v GROUP BY v.city_id, LOWER(TRIM(REPLACE(v.address, '  ', ' '))) HAVING COUNT(*) > 1 ORDER BY v.city_id;

SELECT 'M05_campos_faltantes_venues_marketplace' AS chequeo, COUNT(*) AS venues_marketplace, SUM(TRIM(v.name) = '') AS nombre_vacio, SUM(TRIM(v.address) = '') AS direccion_vacia, SUM(v.capacity IS NULL) AS sin_capacidad, SUM(v.name <> TRIM(v.name) OR v.address <> TRIM(v.address)) AS con_espacios_sobrantes FROM venues v JOIN marketplace_cities mc ON mc.city_id = v.city_id;

SELECT 'M06_campos_faltantes_establecimientos' AS chequeo, COUNT(*) AS establecimientos, SUM(e.organization_id IS NULL) AS sin_organizacion, SUM(e.latitude IS NULL) AS sin_coordenadas, SUM(e.description IS NULL OR TRIM(e.description) = '') AS sin_descripcion, SUM(e.contact_email IS NULL) AS sin_email, SUM(e.contact_phone IS NULL) AS sin_telefono, SUM(NOT EXISTS (SELECT 1 FROM spaces s WHERE s.establishment_id = e.id)) AS sin_espacios, SUM(NOT EXISTS (SELECT 1 FROM spaces s WHERE s.establishment_id = e.id AND s.is_active = 1)) AS sin_espacios_activos FROM establishments e;

SELECT 'M07_establecimientos_por_estado' AS chequeo, s.id AS status_id, s.code, COUNT(e.id) AS establecimientos, COALESCE(SUM(e.id IS NOT NULL AND e.organization_id IS NULL), 0) AS sin_organizacion, COALESCE(SUM(e.id IS NOT NULL AND e.organization_id IS NULL AND s.code <> 'DRAFT'), 0) AS sin_organizacion_y_no_draft FROM establishment_statuses s LEFT JOIN establishments e ON e.status_id = s.id GROUP BY s.id, s.code ORDER BY s.id;

SELECT 'M08_historial_de_estado_establecimientos' AS chequeo, (SELECT COUNT(*) FROM establishments e WHERE NOT EXISTS (SELECT 1 FROM establishment_status_history h WHERE h.establishment_id = e.id)) AS sin_historial, (SELECT COUNT(*) FROM establishments e JOIN establishment_status_history h ON h.establishment_id = e.id WHERE h.id = (SELECT MAX(h2.id) FROM establishment_status_history h2 WHERE h2.establishment_id = e.id) AND h.to_status_id <> e.status_id) AS ultimo_historial_distinto_al_estado, (SELECT COUNT(*) FROM establishment_status_history h WHERE h.note = 'Migrado desde venues, sin propietario asignado') AS historiales_de_backfill, (SELECT COUNT(*) FROM (SELECT establishment_id FROM establishment_status_history WHERE from_status_id IS NULL GROUP BY establishment_id HAVING COUNT(*) > 1) AS d) AS establecimientos_con_varios_historiales_iniciales;

SELECT 'M09_organizaciones' AS chequeo, (SELECT COUNT(*) FROM organizations) AS organizaciones, (SELECT COUNT(*) FROM organizations WHERE is_active = 0) AS inactivas, (SELECT COUNT(*) FROM organization_members) AS miembros, (SELECT COUNT(*) FROM organizations o WHERE NOT EXISTS (SELECT 1 FROM organization_members m JOIN organization_roles r ON r.id = m.organization_role_id WHERE m.organization_id = o.id AND r.code = 'OWNER' AND m.is_active = 1)) AS sin_owner_activo, (SELECT COUNT(*) FROM organizations o WHERE NOT EXISTS (SELECT 1 FROM organization_members m WHERE m.organization_id = o.id AND m.user_id = o.created_by_user_id)) AS creador_no_es_miembro, (SELECT COUNT(*) FROM establishments e JOIN organizations o ON o.id = e.organization_id WHERE o.is_active = 0) AS establecimientos_de_org_inactiva, (SELECT COUNT(*) FROM organization_members m JOIN users u ON u.id = m.user_id WHERE u.is_active = 0 AND m.is_active = 1) AS miembros_activos_con_usuario_inactivo;

SELECT 'M10_concerts_en_venues_con_establecimiento' AS chequeo, COUNT(DISTINCT c.id) AS conciertos, COUNT(DISTINCT c.venue_id) AS venues, (SELECT COUNT(*) FROM concert_reservations) AS conciertos_vinculados_a_reservas FROM concerts c JOIN establishments e ON e.venue_id = c.venue_id;

SELECT 'N01_holds_vencidos_sin_expirar' AS chequeo, r.id, r.space_id, r.created_at, r.hold_expires_at, TIMESTAMPDIFF(MINUTE, r.hold_expires_at, UTC_TIMESTAMP()) AS minutos_vencido, (SELECT COUNT(*) FROM space_occupancy_slots o WHERE o.reservation_id = r.id) AS tramos_retenidos FROM reservations r JOIN reservation_statuses x ON x.id = r.status_id WHERE x.code = 'HOLD' AND r.hold_expires_at <= UTC_TIMESTAMP() ORDER BY r.hold_expires_at;

SELECT 'N02_hold_y_vencimiento_inconsistentes' AS chequeo, r.id, x.code, r.status_is_hold, r.hold_expires_at, r.created_at FROM reservations r JOIN reservation_statuses x ON x.id = r.status_id WHERE (x.code = 'HOLD') <> (r.hold_expires_at IS NOT NULL) OR (r.hold_expires_at IS NOT NULL AND (r.hold_expires_at <= r.created_at OR r.hold_expires_at > r.created_at + INTERVAL 15 MINUTE)) ORDER BY r.id;

SELECT 'N03_resumen_holds' AS chequeo, COUNT(*) AS holds, SUM(r.hold_expires_at > UTC_TIMESTAMP()) AS vigentes, SUM(r.hold_expires_at <= UTC_TIMESTAMP()) AS vencidos, MIN(r.hold_expires_at) AS vencimiento_mas_antiguo, MAX(r.created_at) AS ultimo_creado, MAX(r.created_at) > UTC_TIMESTAMP() AS created_at_en_el_futuro FROM reservations r JOIN reservation_statuses x ON x.id = r.status_id WHERE x.code = 'HOLD';

SELECT 'N04_eventos_programados' AS chequeo, event_name, status, event_type, interval_value, interval_field, last_executed, event_definition FROM information_schema.events WHERE event_schema = DATABASE() ORDER BY event_name;

SELECT 'N05_triggers' AS chequeo, trigger_name, event_object_table, action_timing, event_manipulation FROM information_schema.triggers WHERE trigger_schema = DATABASE() ORDER BY event_object_table, trigger_name;

SELECT 'O01_catalogos_conteo' AS chequeo, 'establishment_statuses' AS catalogo, COUNT(*) AS filas, 5 AS esperadas FROM establishment_statuses UNION ALL SELECT 'O01_catalogos_conteo', 'space_types', COUNT(*), 6 FROM space_types UNION ALL SELECT 'O01_catalogos_conteo', 'features', COUNT(*), 10 FROM features UNION ALL SELECT 'O01_catalogos_conteo', 'space_block_types', COUNT(*), 4 FROM space_block_types UNION ALL SELECT 'O01_catalogos_conteo', 'services', COUNT(*), 8 FROM services UNION ALL SELECT 'O01_catalogos_conteo', 'booking_request_statuses', COUNT(*), 6 FROM booking_request_statuses UNION ALL SELECT 'O01_catalogos_conteo', 'quote_statuses', COUNT(*), 6 FROM quote_statuses UNION ALL SELECT 'O01_catalogos_conteo', 'quote_concepts', COUNT(*), 7 FROM quote_concepts UNION ALL SELECT 'O01_catalogos_conteo', 'reservation_statuses', COUNT(*), 5 FROM reservation_statuses UNION ALL SELECT 'O01_catalogos_conteo', 'card_brands', COUNT(*), 5 FROM card_brands UNION ALL SELECT 'O01_catalogos_conteo', 'payment_statuses', COUNT(*), 4 FROM payment_statuses UNION ALL SELECT 'O01_catalogos_conteo', 'refund_statuses', COUNT(*), 3 FROM refund_statuses UNION ALL SELECT 'O01_catalogos_conteo', 'currencies', COUNT(*), 1 FROM currencies UNION ALL SELECT 'O01_catalogos_conteo', 'payment_methods', COUNT(*), 4 FROM payment_methods UNION ALL SELECT 'O01_catalogos_conteo', 'organization_roles', COUNT(*), 3 FROM organization_roles UNION ALL SELECT 'O01_catalogos_conteo', 'permissions', COUNT(*), 15 FROM permissions UNION ALL SELECT 'O01_catalogos_conteo', 'organization_role_permissions', COUNT(*), 30 FROM organization_role_permissions UNION ALL SELECT 'O01_catalogos_conteo', 'districts', COUNT(*), 1 FROM districts UNION ALL SELECT 'O01_catalogos_conteo', 'marketplace_cities', COUNT(*), 4 FROM marketplace_cities;

SELECT 'O02_permisos_por_rol' AS chequeo, r.code, COUNT(rp.permission_id) AS permisos, CASE r.code WHEN 'OWNER' THEN 15 WHEN 'MANAGER' THEN 13 WHEN 'MEMBER' THEN 2 END AS esperados, GROUP_CONCAT(p.code ORDER BY p.code) AS codigos FROM organization_roles r LEFT JOIN organization_role_permissions rp ON rp.organization_role_id = r.id LEFT JOIN permissions p ON p.id = rp.permission_id GROUP BY r.id, r.code ORDER BY r.id;

SELECT 'O03_metodos_de_pago_y_moneda' AS chequeo, 'payment_methods' AS tabla, code, CAST(requires_card AS CHAR) AS valor FROM payment_methods UNION ALL SELECT 'O03_metodos_de_pago_y_moneda', 'currencies', code, name FROM currencies ORDER BY tabla, code;

SELECT 'O04_estados_establecimiento' AS chequeo, id, code, name FROM establishment_statuses ORDER BY id;

SELECT 'P01_volumen_marketplace' AS chequeo, 'organizations' AS tabla, COUNT(*) AS filas FROM organizations UNION ALL SELECT 'P01_volumen_marketplace', 'organization_members', COUNT(*) FROM organization_members UNION ALL SELECT 'P01_volumen_marketplace', 'establishments', COUNT(*) FROM establishments UNION ALL SELECT 'P01_volumen_marketplace', 'establishment_status_history', COUNT(*) FROM establishment_status_history UNION ALL SELECT 'P01_volumen_marketplace', 'spaces', COUNT(*) FROM spaces UNION ALL SELECT 'P01_volumen_marketplace', 'space_features', COUNT(*) FROM space_features UNION ALL SELECT 'P01_volumen_marketplace', 'space_blocks', COUNT(*) FROM space_blocks UNION ALL SELECT 'P01_volumen_marketplace', 'service_providers', COUNT(*) FROM service_providers UNION ALL SELECT 'P01_volumen_marketplace', 'establishment_services', COUNT(*) FROM establishment_services UNION ALL SELECT 'P01_volumen_marketplace', 'booking_requests', COUNT(*) FROM booking_requests UNION ALL SELECT 'P01_volumen_marketplace', 'quotes', COUNT(*) FROM quotes UNION ALL SELECT 'P01_volumen_marketplace', 'quote_items', COUNT(*) FROM quote_items UNION ALL SELECT 'P01_volumen_marketplace', 'reservations', COUNT(*) FROM reservations UNION ALL SELECT 'P01_volumen_marketplace', 'reservation_services', COUNT(*) FROM reservation_services UNION ALL SELECT 'P01_volumen_marketplace', 'reservation_agreements', COUNT(*) FROM reservation_agreements UNION ALL SELECT 'P01_volumen_marketplace', 'space_occupancy_slots', COUNT(*) FROM space_occupancy_slots UNION ALL SELECT 'P01_volumen_marketplace', 'establishment_slot_modes', COUNT(*) FROM establishment_slot_modes UNION ALL SELECT 'P01_volumen_marketplace', 'payments', COUNT(*) FROM payments UNION ALL SELECT 'P01_volumen_marketplace', 'refunds', COUNT(*) FROM refunds UNION ALL SELECT 'P01_volumen_marketplace', 'concert_reservations', COUNT(*) FROM concert_reservations;

SELECT 'P02_volumen_base' AS chequeo, 'users' AS tabla, COUNT(*) AS filas FROM users UNION ALL SELECT 'P02_volumen_base', 'provinces', COUNT(*) FROM provinces UNION ALL SELECT 'P02_volumen_base', 'cities', COUNT(*) FROM cities UNION ALL SELECT 'P02_volumen_base', 'venues', COUNT(*) FROM venues UNION ALL SELECT 'P02_volumen_base', 'concerts', COUNT(*) FROM concerts;
